/* 输入框提示词 */
.input-area-custom{
  background:transparent !important;
  position:relative !important;
}
.input-box-custom{
  background:transparent !important;
  border:none !important;
  padding-left:42px;
  color:var(--pink-main) !important;
  -webkit-mask-image:none !important;
  background-image:none !important;
  position:relative !important;      /* ⚠️ 建立层叠上下文 */
  z-index:1 !important;              /* ⚠️ 输入框层级较低 */
}
/*原生占位全透明*/
.input-box-custom::placeholder {
  color: transparent !important;
  opacity:0;
}
/*空白显示提示，输入内容父容器匹配，隐藏伪元素*/
.input-area-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  display:none !important;
}
/*自定义提示样式 水平居中 + 往上挪 + 层级在输入框上面 */
.input-area-custom::before {
  content:"是ฅ՞熊猫团子՞ฅ啊";
  color: var(--pink-main) !important;
  position:absolute;
  left:50%;                          /* ⚠️ 水平居中 */
  top:calc(50% - 29px);               /* ⚠️ 垂直往上挪29px，数字越大越往上 */
  transform: translateX(-50%);       /* ⚠️ 只做水平居中，垂直不处理 */
  pointer-events:none;
  font-size:13px;
  white-space:nowrap;                /* ⚠️ 防止文字换行，保证居中准确 */
  z-index:99 !important;             /* ⚠️ 提示词层级高，显示在输入框上面 */
  position:absolute !important;      /* ⚠️ 确保绝对定位生效 */
}
/*原生占位透明保留属性，保证:placeholder-shown正常识别*/
.input-box-custom::placeholder {
  color: transparent !important;
}

